"""Stage 3 gate, rung c: retrain the surrogate with stronger L2 to compress
pre-activation range; measure fidelity vs range at each point. Also evaluates
the REAL Chebyshev polynomial (not the true sigmoid) at candidate degrees over
per-unit domains — the gate's step-3 measurement."""
import json, sys, warnings
import numpy as np, pandas as pd
import xgboost as xgb
from sklearn.neural_network import MLPRegressor
from sklearn.metrics import roc_auc_score, precision_recall_fscore_support
warnings.filterwarnings("ignore")

REPO = sys.argv[1] if len(sys.argv) > 1 else "."
TH = float(np.log(0.64 / 0.36))
fc = json.load(open(f"{REPO}/model/feature_cols.json"))
tr = pd.read_parquet(f"{REPO}/data/cdc_diabetes_train.parquet")
te = pd.read_parquet(f"{REPO}/data/cdc_diabetes_test.parquet")
fu = pd.read_parquet(f"{REPO}/data/cdc_diabetes_prepped.parquet")
Xtr, ytr = tr[fc].to_numpy(np.float32), tr["Diabetes_binary"].to_numpy()
Xte, yte = te[fc].to_numpy(np.float32), te["Diabetes_binary"].to_numpy()
Xfu = fu[fc].to_numpy(np.float32)
m = xgb.XGBClassifier(); m.load_model(f"{REPO}/model/xgb_diabetes_model.json")
lg_tr = np.log(np.clip(m.predict_proba(Xtr)[:, 1], 1e-7, 1 - 1e-7) /
               (1 - np.clip(m.predict_proba(Xtr)[:, 1], 1e-7, 1 - 1e-7)))
lg_te = np.log(m.predict_proba(Xte)[:, 1] / (1 - m.predict_proba(Xte)[:, 1]))
mu, sd = Xtr.mean(0), Xtr.std(0)
Ztr, Zte, Zfu = (Xtr - mu) / sd, (Xte - mu) / sd, (Xfu - mu) / sd
sig = lambda x: 1 / (1 + np.exp(-x))

def poly_forward(Z, W1, b1, W2, b2, dom, deg):
    """Forward pass with the REAL Chebyshev poly per unit (domain-clamped fit)."""
    pre = Z @ W1 + b1
    hid = np.empty_like(pre)
    for j in range(pre.shape[1]):
        lo, hi = dom[j]
        if hi - lo < 1e-6:  # dead unit: constant activation
            hid[:, j] = sig(0.5 * (lo + hi)); continue
        xs = np.linspace(lo, hi, 2049)
        cf = np.polynomial.Chebyshev.fit(xs, sig(xs), deg, domain=[lo, hi])
        hid[:, j] = cf(pre[:, j])
    return (hid @ W2 + b2).ravel(), pre

rows = []
for H in [16, 8]:
    for alpha in [1e-4, 1e-2, 1e-1, 3e-1, 1.0]:
        mlp = MLPRegressor(hidden_layer_sizes=(H,), activation="logistic",
                           solver="adam", alpha=alpha, batch_size=512,
                           learning_rate_init=1e-3, max_iter=60,
                           early_stopping=True, n_iter_no_change=8,
                           validation_fraction=0.1, random_state=42)
        mlp.fit(Ztr, lg_tr)
        W1, W2 = mlp.coefs_; b1, b2 = mlp.intercepts_
        pre_fu = Zfu @ W1 + b1
        lo = pre_fu.min(0); hi = pre_fu.max(0)
        width = float(np.abs(pre_fu).max())
        # exact-sigmoid fidelity
        lg_hat = (sig(Zte @ W1 + b1) @ W2 + b2).ravel()
        auc = roc_auc_score(yte, sig(lg_hat))
        pr, rc, f1, _ = precision_recall_fscore_support(
            yte, (lg_hat >= TH).astype(int), average="binary", zero_division=0)
        agree = float(((lg_hat >= TH) == (lg_te >= TH)).mean())
        # real-polynomial fidelity at candidate degrees (per-unit domains, 5% margin each side)
        span = (hi - lo); dom = np.stack([lo - .05 * span, hi + .05 * span], 1)
        polys = {}
        for deg in [7, 13, 27]:
            plg, _ = poly_forward(Zte, W1, b1, W2, b2, dom, deg)
            ppr, prc, pf1, _ = precision_recall_fscore_support(
                yte, (plg >= TH).astype(int), average="binary", zero_division=0)
            polys[deg] = {"auc": float(roc_auc_score(yte, sig(plg))),
                          "f1": float(pf1), "recall": float(prc),
                          "agree_ref": float(((plg >= TH) == (lg_hat >= TH)).mean()),
                          "max_lgerr": float(np.abs(plg - lg_hat).max())}
        rows.append({"H": H, "alpha": alpha, "max_abs_pre": width,
                     "auc": float(auc), "f1": float(f1), "recall": float(rc),
                     "precision": float(pr), "agree_xgb": agree, "poly": polys})
        print(json.dumps(rows[-1]))
json.dump(rows, open(f"{REPO}/model/surrogate/alpha_sweep.json", "w"), indent=1)
